if doc.custom_company_level == "Global":
    existing_global = frappe.db.get_value("Company", 
        {"custom_company_level": "Global", "name": ["!=", doc.name]}, 
        "name"
    )
    if existing_global:
        frappe.throw(
            title="Validation Error",
            msg=f"You cannot mark <b>{doc.name}</b> as Global.<br><br>The company <b>{existing_global}</b> is already set as Global.<br>Only one Global company is allowed."
        )

# ============================================================
# AUTOMATED EMPLOYEE SUB-ID GENERATOR
# DocType: Employee | Event: Before Validate
# ============================================================

assigned_in_doc = {}

# 1. Map existing IDs already present on this document
for row in doc.get("custom_organization_associations", []):
    if row.organization and row.organization_employee_id:
        assigned_in_doc[row.organization] = row.organization_employee_id

for row in doc.get("custom_organization_ids", []):
    if row.organization and row.org_employee_id:
        assigned_in_doc[row.organization] = row.org_employee_id

generated_sequences = {}

# 2. Auto-generate for custom_organization_associations rows if empty
for row in doc.get("custom_organization_associations", []):
    if not row.organization:
        continue

    # Global company always uses the Master Global Employee ID
    if "global" in row.organization.lower():
        if doc.name and not doc.name.startswith("new-employee"):
            row.organization_employee_id = doc.name
            assigned_in_doc[row.organization] = doc.name
            continue

    if not row.organization_employee_id:
        if row.organization in assigned_in_doc:
            row.organization_employee_id = assigned_in_doc[row.organization]
        else:
            abbr = frappe.db.get_value("Company", row.organization, "abbr") or row.organization[:3]
            prefix = abbr.strip().upper() + "-"

            if prefix not in generated_sequences:
                sub_ids = frappe.db.sql('''
                    SELECT org_employee_id FROM `tabEmployee Sub ID`
                    WHERE org_employee_id LIKE %s
                ''', (f"{prefix}%",), as_dict=True)

                assoc_ids = frappe.db.sql('''
                    SELECT organization_employee_id FROM `tabEmployee Organization Association`
                    WHERE organization_employee_id LIKE %s
                ''', (f"{prefix}%",), as_dict=True)

                numbers = []
                for item in sub_ids:
                    val = item.get("org_employee_id") or ""
                    try:
                        numbers.append(int(val.split("-")[-1]))
                    except:
                        pass
                for item in assoc_ids:
                    val = item.get("organization_employee_id") or ""
                    try:
                        numbers.append(int(val.split("-")[-1]))
                    except:
                        pass

                next_num = max(numbers) + 1 if numbers else 1
                generated_sequences[prefix] = next_num
            else:
                current_num = generated_sequences[prefix]
                generated_sequences[prefix] = current_num + 1

            new_id = f"{prefix}{str(generated_sequences[prefix]).zfill(3)}"
            row.organization_employee_id = new_id
            assigned_in_doc[row.organization] = new_id

# 3. Auto-generate for custom_organization_ids rows if empty
for row in doc.get("custom_organization_ids", []):
    if not row.organization:
        continue

    # Global company always uses the Master Global Employee ID
    if "global" in row.organization.lower():
        if doc.name and not doc.name.startswith("new-employee"):
            row.org_employee_id = doc.name
            assigned_in_doc[row.organization] = doc.name
            if not row.company_abbr:
                abbr = frappe.db.get_value("Company", row.organization, "abbr")
                if abbr:
                    row.company_abbr = abbr.strip().upper()
            continue

    if not row.org_employee_id:
        if row.organization in assigned_in_doc:
            row.org_employee_id = assigned_in_doc[row.organization]
        else:
            abbr = frappe.db.get_value("Company", row.organization, "abbr") or row.organization[:3]
            prefix = abbr.strip().upper() + "-"

            if prefix not in generated_sequences:
                sub_ids = frappe.db.sql('''
                    SELECT org_employee_id FROM `tabEmployee Sub ID`
                    WHERE org_employee_id LIKE %s
                ''', (f"{prefix}%",), as_dict=True)

                assoc_ids = frappe.db.sql('''
                    SELECT organization_employee_id FROM `tabEmployee Organization Association`
                    WHERE organization_employee_id LIKE %s
                ''', (f"{prefix}%",), as_dict=True)

                numbers = []
                for item in sub_ids:
                    val = item.get("org_employee_id") or ""
                    try:
                        numbers.append(int(val.split("-")[-1]))
                    except:
                        pass
                for item in assoc_ids:
                    val = item.get("organization_employee_id") or ""
                    try:
                        numbers.append(int(val.split("-")[-1]))
                    except:
                        pass

                next_num = max(numbers) + 1 if numbers else 1
                generated_sequences[prefix] = next_num
            else:
                current_num = generated_sequences[prefix]
                generated_sequences[prefix] = current_num + 1

            new_id = f"{prefix}{str(generated_sequences[prefix]).zfill(3)}"
            row.org_employee_id = new_id
            assigned_in_doc[row.organization] = new_id

    if row.organization and not row.company_abbr:
        abbr = frappe.db.get_value("Company", row.organization, "abbr")
        if abbr:
            row.company_abbr = abbr.strip().upper()

child_table = doc.get("custom_organization_ids")

if child_table:
    for row in child_table:
        # Only generate if the row has a company selected and the ID is blank
        if row.organization and not row.org_employee_id:
            
            # Fetch the abbreviation (e.g., AQH-IND)
            company_abbr = frappe.db.get_value("Company", row.organization, "abbr")
            
            if company_abbr:
                prefix = company_abbr.strip().upper() + "-"
                
                # Check the database for existing Sub-IDs
                existing_subs = frappe.get_all(
                    "Employee Sub ID",
                    filters={"org_employee_id": ("like", f"{prefix}%")},
                    pluck="org_employee_id"
                )
                
                # Calculate the exact next number without relying on cache!
                if existing_subs:
                    numbers = []
                    for item in existing_subs:
                        if item:
                            try:
                                num = int(item.split("-")[-1])
                                numbers.append(num)
                            except:
                                pass
                    next_sub_num = max(numbers) + 1 if numbers else 1
                else:
                    next_sub_num = 1
                    
                # Stamp the perfect Sub-ID into the row!
                row.org_employee_id = f"{prefix}{str(next_sub_num).zfill(3)}"

cycle_type = frappe.db.get_value("Appraisal Cycle", doc.appraisal_cycle, "custom_cycle_type") or ""
cycle_name = (doc.appraisal_cycle or "").lower()
state = doc.workflow_state or "Pending"

is_mid = (cycle_type == "Mid-Term") or ("mid" in cycle_name) or ("half" in cycle_name)
is_ann = (cycle_type == "Annual") or ("annual" in cycle_name)

# ---------------------------------------------------------
# SCENARIO 1: Updating MID-TERM appraisal
# ---------------------------------------------------------
if is_mid:
    obj_stat = "Pending"
    mid_stat = "Pending"
    
    if state == "Objective Review Pending":
        obj_stat = "Under Review"
    elif state in ["Objectives Approved", "Objectives Rejected"]:
        obj_stat = "Approved"
    elif state == "Pending Manager Review":
        obj_stat = "Approved"
        mid_stat = "Manager Review"
    elif state == "Completed":
        obj_stat = "Approved"
        mid_stat = "Completed"
        
    doc.custom_objective_status = obj_stat
    doc.custom_midterm_status = mid_stat
    doc.custom_annual_status = "N/A"
    
    # Push updates forward to any existing Annual appraisal
    annuals = frappe.get_all(
        "Appraisal", 
        filters={"employee": doc.employee, "name": ["!=", doc.name], "docstatus": ["<", 2]}, 
        fields=["name", "appraisal_cycle", "workflow_state"]
    )
    for a in annuals:
        a_cycle = a.get("appraisal_cycle") or ""
        a_type = frappe.db.get_value("Appraisal Cycle", a_cycle, "custom_cycle_type") or ""
        if (a_type == "Annual") or ("annual" in a_cycle.lower()):
            ann_st = "N/A"
            if mid_stat == "Completed":
                astate = a.get("workflow_state") or "Pending"
                if astate in ["Draft", "Pending"]: 
                    ann_st = "Pending"
                elif astate == "Pending Manager Review": 
                    ann_st = "Manager Review"
                elif astate == "Completed": 
                    ann_st = "Completed"
            
            frappe.db.set_value("Appraisal", a.name, {
                "custom_objective_status": obj_stat,
                "custom_midterm_status": mid_stat,
                "custom_annual_status": ann_st
            })

# ---------------------------------------------------------
# SCENARIO 2: Updating or creating ANNUAL appraisal
# ---------------------------------------------------------
elif is_ann:
    past = frappe.get_all(
        "Appraisal", 
        filters={"employee": doc.employee, "name": ["!=", doc.name], "docstatus": ["<", 2]}, 
        fields=["name", "appraisal_cycle", "workflow_state"], 
        order_by="creation desc"
    )
    
    m_obj = "Pending"
    m_mid = "Pending"
    
    for p in past:
        p_cycle = p.get("appraisal_cycle") or ""
        p_type = frappe.db.get_value("Appraisal Cycle", p_cycle, "custom_cycle_type") or ""
        # Recognizes cycle by custom_cycle_type == 'Mid-Term', name, or linked doc
        if (p_type == "Mid-Term") or ("mid" in p_cycle.lower()) or ("half" in p_cycle.lower()) or (doc.get("custom_linked_midterm_appraisal") == p.name):
            p_state = p.get("workflow_state") or "Pending"
            if p_state == "Objective Review Pending":
                m_obj = "Under Review"
            elif p_state in ["Objectives Approved", "Objectives Rejected"]:
                m_obj = "Approved"
            elif p_state == "Pending Manager Review":
                m_obj = "Approved"
                m_mid = "Manager Review"
            elif p_state == "Completed":
                m_obj = "Approved"
                m_mid = "Completed"
            break
            
    doc.custom_objective_status = m_obj
    doc.custom_midterm_status = m_mid
    
    # Calculate Annual Status based on workflow_state
    if m_mid != "Completed":
        doc.custom_annual_status = "N/A"
    else:
        if state in ["Draft", "Pending"]:
            doc.custom_annual_status = "Pending"
        elif state == "Pending Manager Review":
            doc.custom_annual_status = "Manager Review"
        elif state == "Completed":
            doc.custom_annual_status = "Completed"
        else:
            doc.custom_annual_status = "Pending"
